<body>
<div id="ggbar" data-gg-statusbar="1"><div class="empty">状态同步中…</div></div>
<script>
(function () {
  var waited = 0, RETRY = 10, STEP = 300;
  // 立绘图源：角色键（记录键或名字）→ 图片地址（data: 或 https:），留空显示占位
  var PORTRAITS = {};
  var skyLayer = null;

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function stat() {
    try {
      if (window.Mvu && typeof Mvu.getMvuData === 'function') {
        var d = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
        if (d && d.stat_data) return d.stat_data;
      }
    } catch (e) {}
    try {
      if (typeof getVariables === 'function') {
        var v = getVariables({ type: 'message', message_id: 'latest' });
        if (v && v.stat_data) return v.stat_data;
      }
    } catch (e) {}
    return null;
  }

  function remembered() {
    try { return localStorage.getItem('ggbar-sel'); } catch (e) { return null; }
  }
  function remember(k) {
    try { localStorage.setItem('ggbar-sel', k); } catch (e) {}
  }

  // 星空层：只构建一次，逐星随机相位呼吸；低频流星
  function buildSky() {
    var sky = document.createElement('div');
    sky.className = 'sky';
    var colors = ['#ffffff', '#ffffff', '#ffffff', '#f2ca7a', '#9db4ff'];
    for (var i = 0; i < 26; i++) {
      var b = document.createElement('b');
      var s = (Math.random() * 1.6 + 0.8).toFixed(1);
      b.style.left = (Math.random() * 100).toFixed(1) + '%';
      b.style.top = (Math.random() * 100).toFixed(1) + '%';
      b.style.width = s + 'px';
      b.style.height = s + 'px';
      b.style.background = colors[i % colors.length];
      b.style.setProperty('--d', (2.5 + Math.random() * 3.5).toFixed(2) + 's');
      b.style.setProperty('--dl', (-Math.random() * 5).toFixed(2) + 's');
      sky.appendChild(b);
    }
    var m = document.createElement('i');
    m.className = 'meteor';
    sky.appendChild(m);
    return sky;
  }

  function row(cls, label, val) {
    return '<div class="row ' + cls + '"><span class="tag ' + cls + '">' + label + '</span><span class="lv">' + esc(val) + '</span></div>';
  }

  function view(e) {
    var c = e.c, name = c['名字'] || e.k;
    var fig = PORTRAITS[e.k] || PORTRAITS[name] || '';
    var html = '<div class="stage"><div class="pfig">' +
      (fig ? '<img src="' + esc(fig) + '" alt="">' :
        '<span class="ph">' + esc(name.charAt(0)) + '</span><span class="phlab">立绘位</span>') +
      '</div><div class="pinfo"><div class="pname">' + esc(name) +
      (c['在场'] === true ? '<span class="dot"></span>' : '<span class="offtag">场外</span>') + '</div>';
    if (c['状态']) html += row('g', '状态', c['状态']);
    if (c['心声']) html += row('hv', '心声', c['心声']);
    if (!c['状态'] && !c['心声']) html += '<div class="none">（暂无记录）</div>';
    html += '</div></div>';
    return html;
  }

  function render(s) {
    var root = document.getElementById('ggbar');
    var html = '';
    if (!s) {
      html = '<div class="empty">（状态待同步）</div>';
    } else {
      var env = s['环境'] || {}, cast = s['角色'] || {};
      var envLine = [env['日期'], env['时间'], env['地点']].filter(Boolean).join(' · ');
      var on = [], off = [];
      for (var k in cast) {
        var c = cast[k] || {};
        (c['在场'] === true ? on : off).push({ c: c, k: k });
      }
      var all = on.concat(off);
      if (envLine) html += '<div class="env">' + esc(envLine) + '</div>';
      if (!all.length) {
        html += '<div class="empty">（场上无人）</div>';
      } else {
        var sel = null, saved = remembered();
        for (var i = 0; i < all.length; i++) if (all[i].k === saved) { sel = all[i]; break; }
        if (!sel) sel = all[0];

        html += '<div class="tabs">';
        for (var j = 0; j < all.length; j++) {
          var t = all[j];
          html += '<span class="tab' + (t.k === sel.k ? ' on' : '') + (t.c['在场'] === true ? '' : ' off') +
            '" data-k="' + esc(t.k) + '">' + esc(t.c['名字'] || t.k) + '</span>';
        }
        html += '</div>' + view(sel);
      }
    }
    root.innerHTML = html;
    if (!skyLayer) skyLayer = buildSky();
    root.appendChild(skyLayer);
  }

  document.getElementById('ggbar').addEventListener('click', function (ev) {
    var t = ev.target;
    while (t && t !== this && !(t.classList && t.classList.contains('tab'))) t = t.parentNode;
    if (!t || t === this) return;
    remember(t.getAttribute('data-k'));
    var s = stat();
    if (s) render(s);
  });

  function tick() {
    var s = stat();
    if (s) { render(s); return; }
    if (++waited < RETRY) { setTimeout(tick, STEP); return; }
    render(null);
  }
  tick();
})();
</script>
</body>
</html>
